From 4816a55be863e51928bf8e5484739ce64617c36d Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 04:15:52 +0100
Subject: [PATCH] openconnect: don't close a WebAuth dialog that was already
 deleted

The WebAuth dialog deletes itself when closed, but the pointer to it
was kept, so the next passkey request after the login page reloaded
called close() on freed memory and crashed kded. Track it with QPointer.

BUG: 515706
---
 vpn/openconnect/openconnectauth.cpp | 4 ++--
 1 file changed, 2 insertions(+), 2 deletions(-)

diff --git a/vpn/openconnect/openconnectauth.cpp b/vpn/openconnect/openconnectauth.cpp
index a02b55b67..61b8a858e 100644
--- a/vpn/openconnect/openconnectauth.cpp
+++ b/vpn/openconnect/openconnectauth.cpp
@@ -92,7 +92,7 @@ public:
     QByteArray tokenMode;
     Token token;
     QAtomicPointer<QSemaphore> waitForWebEngineFinish;
-    OpenconnectWebAuthDialog *authDialog;
+    QPointer<OpenconnectWebAuthDialog> authDialog;

     enum LogLevels {
         Error = 0,
@@ -632,7 +632,7 @@ void OpenconnectAuthWidget::handleWebAuthUxStateChanged(QWebEngineWebAuthUxReque
     if (QWebEngineWebAuthUxRequest::WebAuthUxState::Completed == state || QWebEngineWebAuthUxRequest::WebAuthUxState::Cancelled == state) {
         if (d->authDialog)
             d->authDialog->close();
-    } else {
+    } else if (d->authDialog) {
         d->authDialog->updateDisplay();
     }
 }
-- 
2.53.0
